script:
(function () {
  if (window.__gsDisplayEmojiPolicy) return;
  window.__gsDisplayEmojiPolicy = true;
  var emoji = /\p{Extended_Pictographic}|\p{Regional_Indicator}|[\u{1F3FB}-\u{1F3FF}\u{E0020}-\u{E007F}\u200D\u20E3\uFE0E\uFE0F]/gu;
  function clean(value) { return value.replace(emoji, ''); }
  function scrub(node) {
    if (node.nodeType === 3) {
      var parent = node.parentElement;
      if (parent && parent.closest('script,style,textarea')) return;
      var text = clean(node.nodeValue || '');
      if (text !== node.nodeValue) node.nodeValue = text;
      return;
    }
    if (node.nodeType === 1) {
      if (/^(SCRIPT|STYLE|TEXTAREA)$/.test(node.tagName)) return;
      ['title', 'aria-label', 'placeholder', 'alt'].forEach(function (name) {
        if (!node.hasAttribute(name)) return;
        var value = node.getAttribute(name);
        var safe = clean(value);
        if (safe !== value) node.setAttribute(name, safe);
      });
    }
    Array.prototype.forEach.call(node.childNodes || [], scrub);
  }
  new MutationObserver(function (records) {
    records.forEach(function (record) {
      if (record.type === 'childList') Array.prototype.forEach.call(record.addedNodes, scrub);
      else scrub(record.target);
    });
  }).observe(document, { subtree: true, childList: true, characterData: true,
    attributes: true, attributeFilter: ['title', 'aria-label', 'placeholder', 'alt'] });
  scrub(document);
})();
